syntax.pt:
public static tipo Nome(tipo parametro)
{
    return valor;
}

public static tipo Nome(tipo parametro) => valor;   // só uma expressão

Nome(argumento)   // chamar o método

public static void Nome()   // void: não devolve nada

syntax.en:
public static type Name(type parameter)
{
    return value;
}

public static type Name(type parameter) => value;   // a single expression

Name(argument)   // call the method

public static void Name()   // void: returns nothing

example:
static int Triple(int gold) => gold * 3;

static string Greet(string wizard) => "Hello, " + wizard;

int loot = Triple(4);
string message = Greet("Merlin");
